#!/bin/sh
# Compile the relevant source section from the Swift app itself. This works with
# Command Line Tools too (the package tests require Xcode's Testing.framework).
set -eu

repo=$(git rev-parse --show-toplevel)
runner=$(mktemp "${TMPDIR:-/tmp}/token-yugong-vectors.XXXXXX.swift")
trap 'rm -f "$runner"' EXIT

printf '%s\n' 'import Foundation' > "$runner"
printf '%s\n' 'enum PetState: String { case lively, morning, resting, steady, straining }' >> "$runner"
printf '%s\n' 'enum Role: Hashable { case grandson }' >> "$runner"
printf '%s\n' 'enum Tempo { case idle, working, sweating }' >> "$runner"
# Logic.swift is the implementation under test; this includes it verbatim through Pace.
sed -n '/^\/\/ The usage rules/,/^\/\/ MARK: - Visitors/p' "$repo/Sources/TokenPet/Logic.swift" | sed '$d' >> "$runner"
sed -n '/^\/\/ MARK: - Live pace/,$p' "$repo/Sources/TokenPet/Logic.swift" >> "$runner"
printf '%s\n' '
struct VectorMeter: Codable { var pct: Double; var resetsAt: Double?; enum CodingKeys: String, CodingKey { case pct; case resetsAt = "resets_at" } }
struct LogicInput: Codable { var name: String; var source: String; var now: Double; var five: VectorMeter?; var week: VectorMeter? }
struct PaceInput: Codable { struct Event: Codable { var at: Double; var outputTokens: Int; enum CodingKeys: String, CodingKey { case at; case outputTokens = "output_tokens" } }; var name: String; var source: String; var now: Double; var events: [Event] }
struct VectorInputs: Codable { var schema: Int; var logic: [LogicInput]; var pace: [PaceInput] }
struct LogicOutput: Codable { struct ReadingOut: Codable { var five: VectorMeter?; var week: VectorMeter?; var at: Double }; struct Expected: Codable { var state: String; var headlinePct: Double?; var dailyFill: Double?; var resting: Bool; enum CodingKeys: String, CodingKey { case state; case headlinePct = "headline_pct"; case dailyFill = "daily_fill"; case resting } }; var name: String; var source: String; var now: Double; var reading: ReadingOut; var expected: Expected }
struct PaceOutput: Codable { var name: String; var source: String; var now: Double; var events: [PaceInput.Event]; var expectedRate: Double; var expectedLevel: String; enum CodingKeys: String, CodingKey { case name, source, now, events; case expectedRate = "expected_rate"; case expectedLevel = "expected_level" } }
struct VectorOutputs: Codable { var schema: Int; var source: String; var logic: [LogicOutput]; var pace: [PaceOutput] }
func meter(_ value: VectorMeter?) -> Meter? { value.map { Meter(pct: $0.pct, resetsAt: $0.resetsAt.map(Date.init(timeIntervalSince1970:))) } }
let root = URL(fileURLWithPath: CommandLine.arguments[1])
let input = try JSONDecoder().decode(VectorInputs.self, from: Data(contentsOf: root.appendingPathComponent("desktop/shared/usage-pace-vector-inputs.json")))
let logic = input.logic.map { item -> LogicOutput in let now = Date(timeIntervalSince1970: item.now); let reading = Reading(five: meter(item.five), week: meter(item.week), at: now); let snapshot = Logic.evaluate(main: reading, now: now); return LogicOutput(name: item.name, source: item.source, now: item.now, reading: .init(five: item.five, week: item.week, at: item.now), expected: .init(state: String(describing: snapshot.state), headlinePct: snapshot.headline?.pct, dailyFill: snapshot.daily?.fill, resting: snapshot.resting)) }
let pace = input.pace.map { item -> PaceOutput in let now = Date(timeIntervalSince1970: item.now); let rate = Pace.rate(item.events.map { (Date(timeIntervalSince1970: $0.at), $0.outputTokens) }, now: now); var value = Pace(); value.update(rate: rate, now: now); return PaceOutput(name: item.name, source: item.source, now: item.now, events: item.events, expectedRate: rate, expectedLevel: String(describing: value.level)) }
let encoder = JSONEncoder(); encoder.outputFormatting = [.prettyPrinted, .sortedKeys]
try encoder.encode(VectorOutputs(schema: input.schema, source: "Generated by desktop/scripts/export-vectors.sh from Sources/TokenPet/Logic.swift.", logic: logic, pace: pace)).write(to: root.appendingPathComponent("desktop/shared/usage-pace-vectors.json"))' >> "$runner"

swift "$runner" "$repo"
